const MAX_INGREDIENTS = 30;
const MAX_INGREDIENT_AMOUNT = 100000;
const MAX_INGREDIENT_NAME_LENGTH = 50;

const ALLOWED_COOKING_TIMES = ["quick", "medium", "complex"];
const ALLOWED_CUISINES = [
  "german",
  "italian",
  "indian",
  "japanese",
  "gourmet",
  "fusion",
];
const ALLOWED_DIETS = ["vegetarian", "vegan", "keto", "unrestricted"];
const ALLOWED_UNITS = ["gram", "liter", "piece"];

const input = $input.first().json;
const bodyIsObject =
  typeof input.body === "object" &&
  input.body !== null &&
  !Array.isArray(input.body);

const request = bodyIsObject ? input.body : {};
const validationErrors = [];

if (!bodyIsObject) {
  validationErrors.push("Request body must be a JSON object.");
}

validateInteger(request.portionCount, 1, 12, "Portion count");
validateInteger(request.cookingPeopleCount, 1, 3, "Cooking people count");
validateOption(request.cookingTime, ALLOWED_COOKING_TIMES, "Cooking time");
validateOption(request.cuisineStyle, ALLOWED_CUISINES, "Cuisine style");
validateOption(request.dietPreference, ALLOWED_DIETS, "Diet preference");
validateIngredients(request.ingredients);

const isValid = validationErrors.length === 0;
const validatedRequest = isValid
  ? {
      cookingPeopleCount: request.cookingPeopleCount,
      cookingTime: request.cookingTime,
      cuisineStyle: request.cuisineStyle,
      dietPreference: request.dietPreference,
      ingredients: request.ingredients.map(({ amount, name, unit }) => ({
        amount,
        name: name.trim(),
        unit,
      })),
      portionCount: request.portionCount,
    }
  : null;

return [
  {
    json: {
      clientIp: getClientIp(input.headers),
      isValid,
      request: validatedRequest,
      validationErrors,
    },
  },
];

function validateInteger(value, minimum, maximum, label) {
  if (!Number.isInteger(value) || value < minimum || value > maximum) {
    validationErrors.push(
      `${label} must be between ${minimum} and ${maximum}.`,
    );
  }
}

function validateOption(value, allowedValues, label) {
  if (!allowedValues.includes(value)) {
    validationErrors.push(`${label} is invalid.`);
  }
}

function validateIngredients(ingredients) {
  if (!Array.isArray(ingredients) || ingredients.length === 0) {
    validationErrors.push("At least one ingredient is required.");
    return;
  }

  if (ingredients.length > MAX_INGREDIENTS) {
    validationErrors.push(
      `No more than ${MAX_INGREDIENTS} ingredients are allowed.`,
    );
  }

  ingredients.forEach(validateIngredient);
}

function validateIngredient(ingredient, index) {
  if (
    typeof ingredient !== "object" ||
    ingredient === null ||
    Array.isArray(ingredient)
  ) {
    validationErrors.push(`Ingredient ${index + 1} is invalid.`);
    return;
  }

  validateIngredientName(ingredient.name, index);
  validateIngredientAmount(ingredient.amount, index);

  if (!ALLOWED_UNITS.includes(ingredient.unit)) {
    validationErrors.push(`Ingredient ${index + 1} has an invalid unit.`);
  }
}

function validateIngredientName(name, index) {
  if (
    typeof name !== "string" ||
    name.trim().length === 0 ||
    name.trim().length > MAX_INGREDIENT_NAME_LENGTH
  ) {
    validationErrors.push(`Ingredient ${index + 1} has an invalid name.`);
  }
}

function validateIngredientAmount(amount, index) {
  if (
    typeof amount !== "number" ||
    !Number.isFinite(amount) ||
    amount < 0.01 ||
    amount > MAX_INGREDIENT_AMOUNT
  ) {
    validationErrors.push(`Ingredient ${index + 1} has an invalid amount.`);
  }
}

function getClientIp(headers = {}) {
  const forwardedIp = headers["x-forwarded-for"];

  if (typeof forwardedIp === "string" && forwardedIp.length > 0) {
    return forwardedIp.split(",")[0].trim();
  }

  const realIp = headers["x-real-ip"];
  return typeof realIp === "string" && realIp.length > 0
    ? realIp.trim()
    : "127.0.0.1";
}

