parameters.jsCode:
const generatedOutput = $input.first().json.output;
const request = $('Validate recipe request').first().json.request;
const recipes = generatedOutput?.recipes;
const validationErrors = [];

function normalizeName(value) {
  return String(value ?? '').trim().toLowerCase();
}

function addError(recipeIndex, message) {
  validationErrors.push(`Recipe ${recipeIndex + 1}: ${message}`);
}

function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

if (!Array.isArray(recipes) || recipes.length !== 3) {
  validationErrors.push('The AI must return exactly three recipes.');
} else {
  const providedNames = [
    ...new Set(request.ingredients.map(ingredient => normalizeName(ingredient.name))),
  ];

  const providedNameSet = new Set(providedNames);
  const usedTitles = new Set();

  const timeLimits = {
    quick: { min: 1, max: 20 },
    medium: { min: 21, max: 45 },
    complex: { min: 46, max: Number.POSITIVE_INFINITY },
  };

  recipes.forEach((recipe, recipeIndex) => {
    const normalizedTitle = normalizeName(recipe.title);

    if (!normalizedTitle) {
      addError(recipeIndex, 'The title is missing.');
    } else if (usedTitles.has(normalizedTitle)) {
      addError(recipeIndex, 'The title is not unique.');
    }

    usedTitles.add(normalizedTitle);

    if (recipe.cuisineStyle !== request.cuisineStyle) {
      addError(recipeIndex, 'The cuisine style does not match the request.');
    }

    if (recipe.dietPreference !== request.dietPreference) {
      addError(recipeIndex, 'The diet preference does not match the request.');
    }

    if (recipe.cookingTimeCategory !== request.cookingTime) {
      addError(recipeIndex, 'The cooking time category does not match the request.');
    }

    if (recipe.portionCount !== request.portionCount) {
      addError(recipeIndex, 'The portion count does not match the request.');
    }

    if (recipe.cookingPeopleCount !== request.cookingPeopleCount) {
      addError(recipeIndex, 'The number of cooks does not match the request.');
    }

    const selectedTimeLimit = timeLimits[request.cookingTime];

    if (
      !isFiniteNumber(recipe.cookingTimeMinutes) ||
      recipe.cookingTimeMinutes < selectedTimeLimit.min ||
      recipe.cookingTimeMinutes > selectedTimeLimit.max
    ) {
      addError(recipeIndex, 'The cooking duration does not match its category.');
    }

    const availableIngredients = Array.isArray(recipe.availableIngredients)
      ? recipe.availableIngredients
      : [];

    const additionalIngredients = Array.isArray(recipe.additionalIngredients)
      ? recipe.additionalIngredients
      : [];

    const availableNames = new Set(
      availableIngredients
        .map(ingredient => normalizeName(ingredient.name))
        .filter(Boolean),
    );

    const usedProvidedIngredients = providedNames.filter(name =>
      availableNames.has(name),
    );

    const calculatedPercentage = Math.round(
      (usedProvidedIngredients.length / providedNames.length) * 100,
    );

    if (calculatedPercentage < 70) {
      addError(
        recipeIndex,
        `Only ${calculatedPercentage}% of the provided ingredients are used.`,
      );
    }

    if (recipe.usedIngredientPercentage !== calculatedPercentage) {
      addError(
        recipeIndex,
        `The reported ingredient percentage should be ${calculatedPercentage}%.`,
      );
    }

    const unknownAvailableIngredients = [...availableNames].filter(
      name => !providedNameSet.has(name),
    );

    if (unknownAvailableIngredients.length > 0) {
      addError(
        recipeIndex,
        'Additional ingredients were incorrectly listed as available ingredients.',
      );
    }

    if (additionalIngredients.length > 3) {
      addError(recipeIndex, 'More than three additional ingredients are used.');
    }

    const duplicatedAdditionalIngredients = additionalIngredients
      .map(ingredient => normalizeName(ingredient.name))
      .filter(name => providedNameSet.has(name));

    if (duplicatedAdditionalIngredients.length > 0) {
      addError(
        recipeIndex,
        'A provided ingredient was incorrectly listed as an additional ingredient.',
      );
    }

    const steps = Array.isArray(recipe.steps) ? recipe.steps : [];
    const assignedCooks = new Set();

    steps.forEach((step, stepIndex) => {
      if (step.number !== stepIndex + 1) {
        addError(recipeIndex, 'The preparation steps are not numbered sequentially.');
      }

      if (
        !Number.isInteger(step.assignedCook) ||
        step.assignedCook < 1 ||
        step.assignedCook > request.cookingPeopleCount
      ) {
        addError(recipeIndex, `Step ${stepIndex + 1} has an invalid cook assignment.`);
      } else {
        assignedCooks.add(step.assignedCook);
      }

      if (!isFiniteNumber(step.durationMinutes) || step.durationMinutes < 1) {
        addError(recipeIndex, `Step ${stepIndex + 1} has an invalid duration.`);
      }
    });

    if (
      request.cookingPeopleCount > 1 &&
      assignedCooks.size !== request.cookingPeopleCount
    ) {
      addError(recipeIndex, 'The work is not distributed across all requested cooks.');
    }

    const perPortion = recipe.nutritionPerPortion;
    const total = recipe.nutritionTotal;

    if (!perPortion || !total) {
      addError(recipeIndex, 'Nutrition information is incomplete.');
      return;
    }

    const percentageKeys = [
      'proteinPercentage',
      'carbohydratesPercentage',
      'fatPercentage',
    ];

    const percentageSum = percentageKeys.reduce(
      (sum, key) => sum + Number(perPortion[key]),
      0,
    );

    if (!Number.isFinite(percentageSum) || Math.abs(percentageSum - 100) > 2) {
      addError(recipeIndex, 'The macro percentages do not total approximately 100%.');
    }

    const scalableNutritionKeys = [
      'caloriesKcal',
      'proteinGrams',
      'carbohydratesGrams',
      'fatGrams',
    ];

    scalableNutritionKeys.forEach(key => {
      const expectedTotal = Number(perPortion[key]) * request.portionCount;
      const actualTotal = Number(total[key]);
      const tolerance = Math.max(2, expectedTotal * 0.05);

      if (
        !Number.isFinite(expectedTotal) ||
        !Number.isFinite(actualTotal) ||
        Math.abs(actualTotal - expectedTotal) > tolerance
      ) {
        addError(recipeIndex, `${key} is inconsistent with the portion count.`);
      }
    });

    percentageKeys.forEach(key => {
      if (Math.abs(Number(perPortion[key]) - Number(total[key])) > 1) {
        addError(recipeIndex, `${key} differs between per-portion and total values.`);
      }
    });
  });
}

return [
  {
    json: {
      isValid: validationErrors.length === 0,
      request,
      recipes: Array.isArray(recipes) ? recipes : [],
      validationErrors,
    },
  },
];

const recipes = $input.first().json.recipes;
const generationId = String($execution.id);

if (!Array.isArray(recipes) || recipes.length !== 3) {
  throw new Error('Exactly three validated recipes are required for storage.');
}

const rows = recipes.map(recipe => ({
  generation_id: generationId,
  title: recipe.title,
  summary: recipe.summary,
  cuisine_style: recipe.cuisineStyle,
  diet_preference: recipe.dietPreference,
  cooking_time_category: recipe.cookingTimeCategory,
  cooking_time_minutes: recipe.cookingTimeMinutes,
  portion_count: recipe.portionCount,
  cooking_people_count: recipe.cookingPeopleCount,
  used_ingredient_percentage: recipe.usedIngredientPercentage,
  available_ingredients: recipe.availableIngredients,
  additional_ingredients: recipe.additionalIngredients,
  nutrition_per_portion: recipe.nutritionPerPortion,
  nutrition_total: recipe.nutritionTotal,
  steps: recipe.steps,
}));

return [
  {
    json: {
      generationId,
      rows,
    },
  },
];

